from gpiozero import OutputDevice
import time

# BCM pin numbers for the two output devices
OUTPUT_PIN_1 = 17
OUTPUT_PIN_2 = 27

def setup_output_pins(pin1, pin2):
    """Create gpiozero OutputDevice objects for the given pins."""
    try:
        output_device_1 = OutputDevice(pin1)
        output_device_2 = OutputDevice(pin2)
        return output_device_1, output_device_2
    except Exception as setup_error:
        print("GPIO setup failed:", setup_error)
        return None, None

def apply_output_states(output_device_1, output_device_2):
    """Set the output devices to HIGH and then LOW."""
    try:
        output_device_1.on()  # Turn on the first device
        output_device_2.on()  # Turn on the second device
        print("Outputs ON")
    except Exception as apply_error:
        print("Output apply failed:", apply_error)

def apply_output_off(output_device_1, output_device_2):
    """Turn off the output devices."""
    try:
        output_device_1.off()  # Turn off the first device
        output_device_2.off()  # Turn off the second device
        print("Outputs OFF")
    except Exception as off_error:
        print("Output off failed:", off_error)

def main_loop(output_device_1, output_device_2):
    """Repeatedly toggle the output devices."""
    try:
        while True:
            apply_output_states(output_device_1, output_device_2)
            time.sleep(0.1)
            apply_output_off(output_device_1, output_device_2)
            time.sleep(0.1)
    except KeyboardInterrupt:
        print("Program interrupted by user.")
    except Exception as loop_error:
        print("Main loop error:", loop_error)
    finally:
        # Ensure outputs are off on exit
        print("Cleaning up GPIO")
        if output_device_1:
            output_device_1.close()
        if output_device_2:
            output_device_2.close()

if __name__ == "__main__":
    # Set up the output pins
    output_device_1, output_device_2 = setup_output_pins(OUTPUT_PIN_1, OUTPUT_PIN_2)

    if output_device_1 is not None and output_device_2 is not None:
        # Run the main loop
        main_loop(output_device_1, output_device_2)

from gpiozero import PWMOutputDevice
import time
import logging

# Logging for the PWM output controller
logging.basicConfig(level=logging.INFO, format="%(asctime)s %(message)s")

# BCM pins wired to the PWM servo channels
SERVO_PINS = [12, 13, 18, 19, 22, 23]
PWM_DEVICES = {}


def setup_servos():
    """Create PWM output devices for every servo channel."""
    # Build a PWM device for each pin in the list
    for pin_number in SERVO_PINS:
        PWM_DEVICES[pin_number] = PWMOutputDevice(pin_number)


def apply_angle(pwm_device, angle_degrees):
    """Set the PWM duty cycle to a servo angle in degrees."""
    # Clamp the angle so it stays within the valid range
    safe_angle = max(0, min(180, angle_degrees))
    pwm_device.value = safe_angle / 18.0


def run_servos():
    """Continuously update each servo to a fixed angle."""
    try:
        while True:
            # Apply a neutral position to every servo
            for pwm_device in PWM_DEVICES.values():
                apply_angle(pwm_device, 7.0)
            time.sleep(2)
    except KeyboardInterrupt:
        logging.info("Servo control stopped by user")
    finally:
        # Turn off every PWM channel on exit
        for pwm_device in PWM_DEVICES.values():
            pwm_device.close()


if __name__ == "__main__":
    setup_servos()
    run_servos()

