from gpiozero import PWMOutputDevice
import time
import logging

# Logging for the PWM output driver
logging.basicConfig(level=logging.INFO, format="%(asctime)s %(message)s")

# BCM pin map for the PWM-capable GPIO headers
PIN_MAP = {
    "header": [5, 6, 13, 16, 19, 20, 21],
}


def configure_pwm_headers(header_count: int) -> dict:
    """Create and return a dictionary of PWMOutputDevice objects for a given header count."""
    # Each header gets its own PWM channel on the Raspberry Pi
    pwm_devices = {}
    for header_index in range(header_count):
        device_name = f"header{header_index}"
        pwm_devices[device_name] = PWMOutputDevice(PIN_MAP[header_index], frequency=100)
    return pwm_devices


def apply_state(pwm_devices, state_vector: list[int]) -> None:
    """Apply a list of on/off states to the PWM devices."""
    # Each entry in state_vector corresponds to a header device
    for device_name, state_value in zip(pwm_devices, state_vector):
        pwm_devices[device_name].value = state_value / 100.0


def main() -> None:
    """Configure PWM and apply a sample on/off pattern."""
    try:
        # Set up the headers and apply a short on then off pattern
        pwm_devices = configure_pwm_headers(len(PIN_MAP))
        apply_state(pwm_devices, [100, 0, 25, 50, 75, 0, 100])
        time.sleep(1)
        apply_state(pwm_devices, [0, 0, 0, 0, 0, 0, 0])
    except KeyboardInterrupt:
        logging.info("PWM operation interrupted")
    finally:
        # Release every PWM device on exit
        for device_name in pwm_devices:
            pwm_devices[device_name].close()


if __name__ == "__main__":
    main()

from gpiozero import OutputDevice
import time
import sys

# Map of Raspberry Pi GPIO pins to their BCM numbers
PIN_MAP = {
    "header": 4,
    "labeled": 17,
    "unlabeled": 18,
    "power": 22,
    "phone": 23,
    "network": 24,
    "vga": 25,
    "hdmi": 27,
}


def apply_pin_state(pin_name, state):
    """Apply a state ('on' or 'off') to a GPIO pin."""
    try:
        pin = OutputDevice(pin_name, active_high=state == 'on', initial_value=state)
        print(f"Applied '{state}' to {pin_name}")
    except Exception as e:
        print(f"Error setting pin {pin_name}: {e}")
        sys.exit(1)


def read_pin_state(pin_name):
    """Read the current state of a GPIO pin."""
    try:
        pin = OutputDevice(pin_name)
        return pin.value
    except Exception as e:
        print(f"Error reading pin {pin_name}: {e}")
        return None


def main():
    """Main function to continuously monitor and control GPIO pins."""

    try:
        while True:
            # Read the state of each pin
            header_state = read_pin_state("header")
            labeled_state = read_pin_state("labeled")
            unlabeled_state = read_pin_state("unlabeled")
            power_state = read_pin_state("power")
            phone_state = read_pin_state("phone")
            network_state = read_pin_state("network")
            vga_state = read_pin_state("vga")
            hdmi_state = read_pin_state("hdmi")

            # Apply state if reading was successful
            if header_state is not None:
                apply_pin_state("header", header_state)
            if labeled_state is not None:
                apply_pin_state("labeled", labeled_state)
            if unlabeled_state is not None:
                apply_pin_state("unlabeled", unlabeled_state)
            if power_state is not None:
                apply_pin_state("power", power_state)
            if phone_state is not None:
                apply_pin_state("phone", phone_state)
            if network_state is not None:
                apply_pin_state("network", network_state)
            if vga_state is not None:
                apply_pin_state("vga", vga_state)
            if hdmi_state is not None:
                apply_pin_state("hdmi", hdmi_state)

            time.sleep(0.001)

    except KeyboardInterrupt:
        print("Program interrupted by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        sys.exit(1)


if __name__ == "__main__":
    main()

from gpiozero import PWMOutputDevice
import time
import logging

# Configure logging for the PWM control program
logging.basicConfig(level=logging.INFO, format="%(asctime)s %(message)s")

# Define the GPIO pins connected to the PWM devices
PWM_PINS = [4, 12, 23, 24, 25, 27]


def create_pwm_devices(pin_list):
    """Create PWMOutputDevice objects for the given list of GPIO pins."""
    try:
        pwm_devices = []
        for pin_number in pin_list:
            pwm_device = PWMOutputDevice(pin_number)
            pwm_devices.append(pwm_device)
        return pwm_devices
    except Exception as create_error:
        logging.error("Failed to create PWM devices: %s", create_error)
        return None


def apply_pwm_value(pwm_device, value):
    """Apply a PWM value to a single PWM device."""
    try:
        pwm_device.value = value
        logging.info("PWM applied to pin %s value %s", pwm_device.pin.no, value)
    except Exception as apply_error:
        logging.error("Failed to apply PWM value: %s", apply_error)


def run_pwm_loop(pwm_devices, repeat_count=1, delay_seconds=2):
    """Repeatedly apply a fixed PWM value to each PWM device."""
    if pwm_devices is None:
        return

    try:
        for _ in range(repeat_count):
            for pwm_device in pwm_devices:
                apply_pwm_value(pwm_device, 0.5)
            time.sleep(delay_seconds)
    except KeyboardInterrupt:
        logging.info("PWM loop interrupted by user.")
    except Exception as loop_error:
        logging.error("PWM loop failed: %s", loop_error)
    finally:
        # Turn off all PWM devices on exit
        for pwm_device in pwm_devices:
            pwm_device.value = 0
        logging.info("PWM devices set to 0.")


if __name__ == "__main__":
    # Initialize PWM devices on the Raspberry Pi
    pwm_devices = create_pwm_devices(PWM_PINS)
    if pwm_devices:
        run_pwm_loop(pwm_devices)

