    """Create gpiozero OutputDevice objects for each pin."""
    output_devices = []
    for pin_number in pin_numbers:
        output_device = OutputDevice(pin_number)
        output_devices.append(output_device)
    return output_devices

def apply_output_states(output_devices, states):
    """Apply a list of states to the output devices."""
    for device, state in zip(output_devices, states):
