    """Main function to toggle the output pins."""
    output_devices = setup_output_pins(OUTPUT_PINS)
    try:
        while True:
            # Alternate the output states
            apply_output_states(output_devices, ["on", "off"])
            time.sleep(0.5)
    except KeyboardInterrupt:
        print("Program interrupted by user")
    finally:
        # Release the GPIO pins
        for device in output_devices:
            device.close()

